final class TorchController {
    var isOn = false
    var action: (() -> Void)?
    func configure() {
        action = { [weak self] in
            guard let self else { return }
            print(self.isOn)
        }
    }
}
var controller: TorchController? = TorchController()
controller?.configure()
weak var probe = controller
let action = controller?.action
controller = nil
print(probe == nil)
action?()

Слабый захват разрывает controller → action → controller. Вывод true, внешний вызов action после закрытия ничего не печатает.

